import streamlit as st
from pathlib import Path
import os
APP_NAME="Calidad MD | PNC y ME"
LOGO_MUNDO_DULCE_BASE64=''
BASE_DIR = Path(__file__).resolve().parent


def _configuracion_secreta(nombre, predeterminado=""):
    """Obtiene una variable desde Streamlit Secrets o desde el entorno."""
    valor_entorno = os.getenv(nombre, predeterminado)
    try:
        valor = st.secrets.get(nombre, valor_entorno)
    except Exception:
        valor = valor_entorno
    return str(valor or "").strip()


FORCE_RESET_ADMIN = _configuracion_secreta("CALIDAD_FORCE_RESET_ADMIN", "0") == "1"
ADMIN_USER = _configuracion_secreta("CALIDAD_ADMIN_USER", "admin") or "admin"
ADMIN_PASS = _configuracion_secreta("CALIDAD_ADMIN_PASS", "")
